import {studioZip} from './studio-zip.js';
window.downloadStudioPackage=async(jobId,briefOnly=false)=>{const status=document.getElementById('job-status');async function get(path){const response=await fetch(path),data=await response.json();if(!response.ok)throw Error(data.error);return data;}try{status.textContent='Preparing project package…';const data=await get('/api/studio/jobs?archived=1&selected='+encodeURIComponent(jobId)),job=data.jobs.find(j=>j.id===jobId);if(!job)throw Error('This creative job could not be found.');const report={title:job.title,brief:job.brief,stage:job.stage,production:job.production||null,measurement:job.measurement||null,learning:job.learning||'',exportedAt:new Date().toISOString(),notice:'Private project export. Review notes and assets before sharing. No file was published or sent.'};const files=[{name:'project-brief.json',data:JSON.stringify(report,null,2)},{name:'READ-ME.txt',data:'Bonga Bhengu Creative Studio\n'+job.title+'\n\n'+job.brief+'\n\nThis package contains your saved project files. Review the contents before sharing. Measurements, if included, were entered by the owner and are not verified platform analytics.\n'}];const assetIds=[...new Set([...job.mediaIds,...(job.production?.logoMediaId?[job.production.logoMediaId]:[])])];if(!briefOnly&&assetIds.length){const library=await get('/api/designer/media'),assets=assetIds.map(id=>library.files.find(f=>f.id===id));if(assets.some(f=>!f))throw Error('A project file or logo was removed. Download the brief only, or restore the missing file first.');if(assets.reduce((sum,f)=>sum+f.size,0)>100*1048576)throw Error('Attached files exceed the 100 MB package limit. Use Download brief only and download large media separately.');for(const [index,file]of assets.entries()){status.textContent='Preparing file '+(index+1)+' / '+assets.length+' · '+file.name;const response=await fetch(file.url);if(!response.ok)throw Error('Could not read '+file.name);const bytes=new Uint8Array(await response.arrayBuffer());if(bytes.length!==file.size)throw Error('Incomplete file: '+file.name);const name=(index+1)+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_').replace(/\.\./g,'_');files.push({name:'media/'+name,data:bytes});}}const zip=studioZip(files),url=URL.createObjectURL(zip),a=document.createElement('a');a.href=url;a.download=(job.title.replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,70)||'studio-project')+(briefOnly?'-brief':'-package')+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='Project package downloaded. Review its contents before sharing.';}catch(e){status.textContent=e.message;throw e;}};
